var n=`0766-mishkaki`;var r=`world-0766`;var s=`TZ`;var a=`eastern-africa`;var t=4;var o=108;var g={en:`Mishkaki`,ua:`Мішкакі`};var l={en:`Mishkaki is a Tanzania classic prepared with beef sirloin, garlic, ginger root, lemon juice. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Мішкакі, страва кухні країни Танзанія зі складниками: яловичий сирлойн, часник, корінь імбиру, лимонний сік. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 75 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 75 хвилин.`,t:[`marinating`],m:75,i:[[`beef-sirloin`,710,`g`],[`garlic`,5,`clove`],[`ginger-root`,25,`g`],[`lemon-juice`,45,`ml`],[`hot-paprika`,7,`g`],[`ground-cumin`,5,`g`]]},{en:`Thread the prepared pieces onto skewers, leaving small gaps to ensure even cooking.`,ua:`Нанизайте підготовлені шматочки на шампури чи шпажки, залишаючи невеликі проміжки для рівномірного приготування.`,t:[`threading-skewers`],m:12,i:[[`red-bell-pepper`,180,`g`],[`yellow-onion`,140,`g`]]},{en:`Grill over medium-high heat for about 18 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 18 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:18,i:[[`sunflower-oil`,40,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lime`,2,`pcs`]]}];var d={slug:n,id:r,country:`TZ`,region:a,servings:4,minutes:108,title:g,text:l,steps:u};export{s as country,d as default,r as id,o as minutes,a as region,t as servings,n as slug,u as steps,l as text,g as title};